head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getCellChecked]<br/>Row 인덱스와 Column 정보를 사용하여 특정 Body Cell 의 체크 상태를 반환합니다. inputType 이 'checkbox','radio','custom' 인 경우에만 동작합니다.",
    "validation" : [
        "valueType='binary' 이면 trueValue '1' / falseValue '0', valueType='boolean' 이면 trueValue 'true' / falseValue 'false' 를 기준으로 판단하여 리턴값으로 true / false 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // valueType 판단기준 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - colBin(binary) / colBool(boolean) : trueValue/falseValue("Y"/"N") 무시하고 강제로 1·0 / true·false 로 판단
    //  - colOther(other) : 이때만 명시한 trueValue("Y")/falseValue("N") 적용
    $c.gcm.createLabel('label="colBin(binary)·colBool(boolean): trueValue/falseValue 무시하고 1·0 / true·false 로 판단 / colOther(other): 명시 Y·N 적용"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    //  - colBin  : checkbox(valueType=binary)  데이터 1/0
    //  - colBool : checkbox(valueType=boolean) 데이터 true/false
    //  - colOther: checkbox(valueType=other)   데이터 Y/N (대조군)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="colBin" name="colBin" dataType="text"></w2:column>';
    strDlt += '<w2:column id="colBool" name="colBool" dataType="text"></w2:column>';
    strDlt += '<w2:column id="colOther" name="colOther" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 각 컬럼 체크/미체크 혼합
    //  Row0 : colBin "1"(체크), colBool "true"(체크), colOther "Y"(체크)
    //  Row1 : colBin "0"(미체크), colBool "false"(미체크), colOther "N"(미체크)
    //  Row2 : colBin "1"(체크), colBool "true"(체크), colOther "Y"(체크)
    //  Row3 : colBin "0"(미체크), colBool "false"(미체크), colOther "N"(미체크)
    let jsonData = [
        { "name": "John", "colBin": "1", "colBool": "true",  "colOther": "Y", "memo": "메모0" },
        { "name": "Jane", "colBin": "0", "colBool": "false", "colOther": "N", "memo": "메모1" },
        { "name": "Mike", "colBin": "1", "colBool": "true",  "colOther": "Y", "memo": "메모2" },
        { "name": "Amy",  "colBin": "0", "colBool": "false", "colOther": "N", "memo": "메모3" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 5컬럼)
    // 마지막 memo 컬럼 width="*" 로 가로 스크롤 방지
    // colBin / colBool / colOther : trueValue="Y" falseValue="N" 로 일부러 비기본값 지정
    //  → valueType 이 binary/boolean 이면 이 명시값을 무시하고 강제 1·0 / true·false 로 판단함을 격리 검증
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:720px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getCellChecked valueType 판단기준 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol2" value="colBin(binary)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol3" value="colBool(boolean)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol4" value="colOther(other)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="memo(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : colBin (checkbox, valueType=binary) - trueValue/falseValue 비기본값 "Y"/"N" → 무시되어야 함
    strTarget += '<w2:column width="150" style="" inputType="checkbox" valueType="binary" id="colBin" dataList="colBin" trueValue="Y" falseValue="N"></w2:column>';
    // index 2 : colBool (checkbox, valueType=boolean) - trueValue/falseValue 비기본값 "Y"/"N" → 무시되어야 함
    strTarget += '<w2:column width="150" style="" inputType="checkbox" valueType="boolean" id="colBool" dataList="colBool" trueValue="Y" falseValue="N"></w2:column>';
    // index 3 : colOther (checkbox, valueType=other) - 명시한 trueValue="Y"/falseValue="N" 적용 (대조군)
    strTarget += '<w2:column width="150" style="" inputType="checkbox" valueType="other" id="colOther" dataList="colOther" trueValue="Y" falseValue="N"></w2:column>';
    // index 4 : memo (text) - width="*"
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getCellChecked 확인 : par_rowIndex / par_columnInfo(컬럼 ID) 로 호출 → 체크 상태(true/false) 반환
//  - colBin(binary)  : 데이터 "1" → true (trueValue="Y" 무시, 강제 1 로 판단), "0" → false
//  - colBool(boolean): 데이터 "true" → true (trueValue="Y" 무시, 강제 true 로 판단), "false" → false
//  - colOther(other) : 데이터 "Y" → true (이때만 명시 trueValue="Y" 적용), "N" → false
scwin.btn_getCellChecked_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    // columnInfo 는 컬럼 ID(String) 로 전달
    let colInfo = par_columnInfo.getValue();
    let rtn = target1.getCellChecked(rowIndex, colInfo);
    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }
    wf_body_bottom.getObj("scwin").setReturnValue("getCellChecked(" + rowIndex + ", '" + colInfo + "') : " + rtn);
}
